export interface BeadVerse {
  /** matches a Step's slug exactly, e.g. 'annunciation-hail-mary-9' */
  slug: string;
  /** human-readable citation, e.g. "Lk 1:26-27" */
  ref: string;
  /** Douay-Rheims (public domain) English text for this verse/verse-range */
  en: string;
  /** CGKPV (Nhóm Phiên Dịch Các Giờ Kinh Phụng Vụ) Vietnamese text for the same verse(s) */
  vi: string;
}

export function getBeadVerse(slug: string): BeadVerse | undefined {
  return beadVerses.find((v) => v.slug === slug);
}

// One scripture verse (or verse-range) per Hail Mary bead, modeled on visualrosary.org's
// selection of references per bead, but independently sourced: English is the public-domain
// Douay-Rheims translation, Vietnamese is the CGKPV translation. Where visualrosary.org's own
// on-page citation was ambiguous or flaky, the verse boundary was resolved from the quoted
// content and cross-checked against the source text.
export const beadVerses: BeadVerse[] = [
  // ── Joyful: annunciation (Lk 1:26-38) ──
  { slug: 'annunciation-hail-mary-1', ref: 'Lk 1:26-27', en: `And in the sixth month, the angel Gabriel was sent from God into a city of Galilee, called Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin's name was Mary.`, vi: `Bà Ê-li-sa-bét có thai được sáu tháng, thì Thiên Chúa sai sứ thần Gáp-ri-en đến một thành miền Ga-li-lê, gọi là Na-da-rét, gặp một trinh nữ đã thành hôn với một người tên là Giu-se, thuộc dòng dõi vua Đa-vít. Trinh nữ ấy tên là Ma-ri-a.` },
  { slug: 'annunciation-hail-mary-2', ref: 'Lk 1:28', en: `And the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women.`, vi: `Sứ thần vào nhà trinh nữ và nói: "Mừng vui lên, hỡi Đấng đầy ân sủng, Đức Chúa ở cùng bà."` },
  { slug: 'annunciation-hail-mary-3', ref: 'Lk 1:29', en: `Who having heard, was troubled at his saying, and thought with herself what manner of salutation this should be.`, vi: `Nghe lời ấy, bà rất bối rối, và tự hỏi lời chào như vậy có nghĩa gì.` },
  { slug: 'annunciation-hail-mary-4', ref: 'Lk 1:30', en: `And the angel said to her: Fear not, Mary, for thou hast found grace with God.`, vi: `Sứ thần liền nói: "Thưa bà Ma-ri-a, xin đừng sợ, vì bà đẹp lòng Thiên Chúa."` },
  { slug: 'annunciation-hail-mary-5', ref: 'Lk 1:31', en: `Behold thou shalt conceive in thy womb, and shalt bring forth a son; and thou shalt call his name Jesus.`, vi: `Và này đây bà sẽ thụ thai, sinh hạ một con trai, và đặt tên là Giê-su.` },
  { slug: 'annunciation-hail-mary-6', ref: 'Lk 1:32', en: `He shall be great, and shall be called the Son of the most High; and the Lord God shall give unto him the throne of David his father; and he shall reign in the house of Jacob for ever.`, vi: `Người sẽ nên cao cả, và sẽ được gọi là Con Đấng Tối Cao. Đức Chúa là Thiên Chúa sẽ ban cho Người ngai vàng vua Đa-vít, tổ tiên Người.` },
  { slug: 'annunciation-hail-mary-7', ref: 'Lk 1:33', en: `And of his kingdom there shall be no end.`, vi: `Người sẽ trị vì nhà Gia-cóp đến muôn đời, và triều đại của Người sẽ vô cùng vô tận.` },
  { slug: 'annunciation-hail-mary-8', ref: 'Lk 1:34', en: `And Mary said to the angel: How shall this be done, because I know not man?`, vi: `Bà Ma-ri-a thưa với sứ thần: "Việc ấy sẽ xảy ra cách nào, vì tôi không biết đến việc vợ chồng!"` },
  { slug: 'annunciation-hail-mary-9', ref: 'Lk 1:35', en: `And the angel answering, said to her: The Holy Ghost shall come upon thee, and the power of the most High shall overshadow thee. And therefore also the Holy which shall be born of thee shall be called the Son of God.`, vi: `Sứ thần đáp: "Thánh Thần sẽ ngự xuống trên bà, và quyền năng Đấng Tối Cao sẽ rợp bóng trên bà, vì thế, Đấng Thánh sắp sinh ra sẽ được gọi là Con Thiên Chúa."` },
  { slug: 'annunciation-hail-mary-10', ref: 'Lk 1:38', en: `And Mary said: Behold the handmaid of the Lord; be it done to me according to thy word. And the angel departed from her.`, vi: `Bấy giờ bà Ma-ri-a nói: "Vâng, tôi đây là nữ tỳ của Chúa, xin Chúa cứ làm cho tôi như lời sứ thần nói." Rồi sứ thần từ biệt ra đi.` },

  // ── Joyful: visitation (Lk 1:39-53) ──
  { slug: 'visitation-hail-mary-1', ref: 'Lk 1:39-40', en: `And Mary rising up in those days, went into the hill country with haste into a city of Juda. And she entered into the house of Zachary, and saluted Elizabeth.`, vi: `Hồi ấy, bà Ma-ri-a vội vã lên đường, đến miền núi, vào một thành thuộc chi tộc Giu-đa. Bà vào nhà ông Da-ca-ri-a và chào hỏi bà Ê-li-sa-bét.` },
  { slug: 'visitation-hail-mary-2', ref: 'Lk 1:41', en: `And it came to pass, that when Elizabeth heard the salutation of Mary, the infant leaped in her womb. And Elizabeth was filled with the Holy Ghost:`, vi: `Bà Ê-li-sa-bét vừa nghe tiếng bà Ma-ri-a chào, thì đứa con trong bụng nhảy lên, và bà được đầy tràn Thánh Thần,` },
  { slug: 'visitation-hail-mary-3', ref: 'Lk 1:42', en: `And she cried out with a loud voice, and said: Blessed art thou among women, and blessed is the fruit of thy womb.`, vi: `liền kêu lớn tiếng và nói rằng: "Em được chúc phúc hơn mọi người phụ nữ, và người con em đang cưu mang cũng được chúc phúc."` },
  { slug: 'visitation-hail-mary-4', ref: 'Lk 1:45', en: `And blessed art thou that hast believed, because those things shall be accomplished that were spoken to thee by the Lord.`, vi: `Em thật có phúc, vì đã tin rằng Chúa sẽ thực hiện những gì Người đã nói với em."` },
  { slug: 'visitation-hail-mary-5', ref: 'Lk 1:46-47', en: `And Mary said: My soul doth magnify the Lord. And my spirit hath rejoiced in God my Saviour.`, vi: `Bấy giờ bà Ma-ri-a nói: "Linh hồn tôi ngợi khen Đức Chúa, thần trí tôi hớn hở vui mừng vì Thiên Chúa, Đấng cứu độ tôi.` },
  { slug: 'visitation-hail-mary-6', ref: 'Lk 1:48-49', en: `Because he hath regarded the humility of his handmaid; for behold from henceforth all generations shall call me blessed. Because he that is mighty, hath done great things to me; and holy is his name.`, vi: `Phận nữ tỳ hèn mọn, Người đoái thương nhìn tới; từ nay, hết mọi đời sẽ khen tôi diễm phúc. Đấng Toàn Năng đã làm cho tôi biết bao điều cao cả, danh Người thật chí thánh chí tôn!` },
  { slug: 'visitation-hail-mary-7', ref: 'Lk 1:50', en: `And his mercy is from generation unto generations, to them that fear him.`, vi: `Đời nọ tới đời kia, Chúa hằng thương xót những ai kính sợ Người.` },
  { slug: 'visitation-hail-mary-8', ref: 'Lk 1:51', en: `He hath shewed might in his arm: he hath scattered the proud in the conceit of their heart.`, vi: `Chúa giơ tay biểu dương sức mạnh, dẹp tan phường lòng trí kiêu căng.` },
  { slug: 'visitation-hail-mary-9', ref: 'Lk 1:52', en: `He hath put down the mighty from their seat, and hath exalted the humble.`, vi: `Chúa hạ bệ những ai quyền thế, Người nâng cao mọi kẻ khiêm nhường.` },
  { slug: 'visitation-hail-mary-10', ref: 'Lk 1:53', en: `He hath filled the hungry with good things; and the rich he hath sent empty away.`, vi: `Kẻ đói nghèo, Chúa ban của đầy dư, người giàu có, lại đuổi về tay trắng.` },

  // ── Joyful: nativity (Lk 2:6-19; Mt 2:11) ──
  { slug: 'nativity-hail-mary-1', ref: 'Lk 2:6', en: `And it came to pass, that when they were there, her days were accomplished, that she should be delivered.`, vi: `Khi hai người đang ở đó, thì bà Ma-ri-a đã tới ngày mãn nguyệt khai hoa.` },
  { slug: 'nativity-hail-mary-2', ref: 'Lk 2:7', en: `And she brought forth her firstborn son, and wrapped him up in swaddling clothes, and laid him in a manger; because there was no room for them in the inn.`, vi: `Bà sinh con trai đầu lòng, lấy tã bọc con, rồi đặt nằm trong máng cỏ, vì hai ông bà không tìm được chỗ trong nhà trọ.` },
  { slug: 'nativity-hail-mary-3', ref: 'Lk 2:7', en: `And she brought forth her firstborn son, and wrapped him up in swaddling clothes, and laid him in a manger; because there was no room for them in the inn.`, vi: `Bà sinh con trai đầu lòng, lấy tã bọc con, rồi đặt nằm trong máng cỏ, vì hai ông bà không tìm được chỗ trong nhà trọ.` },
  { slug: 'nativity-hail-mary-4', ref: 'Lk 2:8-9', en: `And there were in the same country shepherds watching, and keeping the night watches over their flock. And behold an angel of the Lord stood by them, and the brightness of God shone round about them; and they feared with a great fear.`, vi: `Trong vùng ấy, có những người chăn chiên sống ngoài đồng và thức đêm canh giữ đàn vật. Bỗng sứ thần Chúa đứng bên họ, và vinh quang của Chúa chiếu toả chung quanh, khiến họ kinh khiếp hãi hùng.` },
  { slug: 'nativity-hail-mary-5', ref: 'Lk 2:10', en: `And the angel said to them: Fear not; for, behold, I bring you good tidings of great joy, that shall be to all the people:`, vi: `Nhưng sứ thần bảo họ: "Anh em đừng sợ. Này tôi báo cho anh em một tin mừng trọng đại, cũng là tin mừng cho toàn dân:` },
  { slug: 'nativity-hail-mary-6', ref: 'Lk 2:11', en: `For, this day, is born to you a Saviour, who is Christ the Lord, in the city of David.`, vi: `Hôm nay, một Đấng Cứu Độ đã sinh ra cho anh em trong thành vua Đa-vít, Người là Đấng Ki-tô Đức Chúa."` },
  { slug: 'nativity-hail-mary-7', ref: 'Lk 2:14', en: `Glory to God in the highest; and on earth peace to men of good will.`, vi: `"Vinh danh Thiên Chúa trên trời, bình an dưới thế cho loài người Chúa thương."` },
  { slug: 'nativity-hail-mary-8', ref: 'Mt 2:11', en: `And entering into the house, they found the child with Mary his mother, and falling down they adored him; and opening their treasures, they offered him gifts; gold, frankincense, and myrrh.`, vi: `Họ vào nhà, thấy Hài Nhi với thân mẫu là bà Ma-ri-a, liền sấp mình thờ lạy Người. Rồi họ mở bảo tráp, lấy vàng, nhũ hương và mộc dược mà dâng tiến.` },
  { slug: 'nativity-hail-mary-9', ref: 'Mt 2:11', en: `And entering into the house, they found the child with Mary his mother, and falling down they adored him; and opening their treasures, they offered him gifts; gold, frankincense, and myrrh.`, vi: `Họ vào nhà, thấy Hài Nhi với thân mẫu là bà Ma-ri-a, liền sấp mình thờ lạy Người. Rồi họ mở bảo tráp, lấy vàng, nhũ hương và mộc dược mà dâng tiến.` },
  { slug: 'nativity-hail-mary-10', ref: 'Lk 2:19', en: `But Mary kept all these words, pondering them in her heart.`, vi: `Còn bà Ma-ri-a thì hằng ghi nhớ mọi kỷ niệm ấy, và suy đi nghĩ lại trong lòng.` },

  // ── Joyful: presentation (Lk 2:22-39) ──
  { slug: 'presentation-hail-mary-1', ref: 'Lk 2:22', en: `And after the days of her purification, according to the law of Moses, were accomplished, they carried him to Jerusalem, to present him to the Lord:`, vi: `Khi đã đến ngày lễ thanh tẩy của các ngài theo luật Mô-sê, bà Ma-ri-a và ông Giu-se đem con lên Giê-ru-sa-lem, để tiến dâng cho Chúa,` },
  { slug: 'presentation-hail-mary-2', ref: 'Lk 2:25', en: `And behold there was a man in Jerusalem named Simeon, and this man was just and devout, waiting for the consolation of Israel; and the Holy Ghost was in him.`, vi: `Hồi ấy ở Giê-ru-sa-lem, có một người tên là Si-mê-ôn. Ông là người công chính và sùng đạo, ông những mong chờ niềm an ủi của Ít-ra-en, và Thánh Thần hằng ngự trên ông.` },
  { slug: 'presentation-hail-mary-3', ref: 'Lk 2:26', en: `And he had received an answer from the Holy Ghost, that he should not see death, before he had seen the Christ of the Lord.`, vi: `Ông đã được Thánh Thần linh báo cho biết là ông sẽ không thấy cái chết trước khi được thấy Đấng Ki-tô của Đức Chúa.` },
  { slug: 'presentation-hail-mary-4', ref: 'Lk 2:27-28', en: `And he came by the Spirit into the temple. And when his parents brought in the child Jesus, to do for him according to the custom of the law, He also took him into his arms, and blessed God, and said:`, vi: `Được Thần Khí thúc đẩy, ông lên Đền Thờ. Vào lúc cha mẹ Hài Nhi Giê-su đem con tới để chu toàn tập tục Luật đã truyền liên quan đến Người, thì ông ẵm lấy Hài Nhi trên tay, và chúc tụng Thiên Chúa rằng:` },
  { slug: 'presentation-hail-mary-5', ref: 'Lk 2:29', en: `Now thou dost dismiss thy servant, O Lord, according to thy word in peace;`, vi: `"Muôn lạy Chúa, giờ đây theo lời Ngài đã hứa, xin để tôi tớ này được an bình ra đi.` },
  { slug: 'presentation-hail-mary-6', ref: 'Lk 2:30-31', en: `Because my eyes have seen thy salvation, Which thou hast prepared before the face of all peoples:`, vi: `Vì chính mắt con được thấy ơn cứu độ Chúa đã dành sẵn cho muôn dân:` },
  { slug: 'presentation-hail-mary-7', ref: 'Lk 2:32', en: `A light to the revelation of the Gentiles, and the glory of thy people Israel.`, vi: `Đó là ánh sáng soi đường cho dân ngoại, là vinh quang của Ít-ra-en Dân Ngài."` },
  { slug: 'presentation-hail-mary-8', ref: 'Lk 2:34', en: `And Simeon blessed them, and said to Mary his mother: Behold this child is set for the fall, and for the resurrection of many in Israel, and for a sign which shall be contradicted;`, vi: `Ông Si-mê-ôn chúc phúc cho hai ông bà, và nói với bà Ma-ri-a, mẹ của Hài Nhi: "Thiên Chúa đã đặt cháu bé này làm duyên cớ cho nhiều người Ít-ra-en ngã xuống hay đứng lên. Cháu còn là dấu hiệu cho người đời chống báng;` },
  { slug: 'presentation-hail-mary-9', ref: 'Lk 2:34-35', en: `And thy own soul a sword shall pierce, that, out of many hearts, thoughts may be revealed.`, vi: `và như vậy, những ý nghĩ từ thâm tâm nhiều người sẽ lộ ra. Còn chính bà, một lưỡi gươm sẽ đâm thâu tâm hồn bà."` },
  { slug: 'presentation-hail-mary-10', ref: 'Lk 2:39', en: `And after they had performed all things according to the law of the Lord, they returned into Galilee, to their city Nazareth.`, vi: `Khi hai ông bà đã làm xong mọi việc như Luật Chúa truyền, thì trở về nơi cư ngụ là thành Na-da-rét, miền Ga-li-lê.` },

  // ── Joyful: finding (Lk 2:42-51) ──
  { slug: 'finding-hail-mary-1', ref: 'Lk 2:42', en: `And when he was twelve years old, they going up into Jerusalem, according to the custom of the feast,`, vi: `Khi Người được mười hai tuổi, cả gia đình cùng lên đền, như người ta thường làm trong ngày lễ.` },
  { slug: 'finding-hail-mary-2', ref: 'Lk 2:43', en: `And having fulfilled the days, when they returned, the child Jesus remained in Jerusalem; and his parents knew it not.`, vi: `Xong kỳ lễ, hai ông bà trở về, còn cậu bé Giê-su thì ở lại Giê-ru-sa-lem, mà cha mẹ chẳng hay biết.` },
  { slug: 'finding-hail-mary-3', ref: 'Lk 2:45-46', en: `And not finding him, they returned into Jerusalem, seeking him. And it came to pass, that, after three days, they found him in the temple, sitting in the midst of the doctors, hearing them, and asking them questions.`, vi: `Không thấy con đâu, hai ông bà trở lại Giê-ru-sa-lem mà tìm. Sau ba ngày, hai ông bà mới tìm thấy con trong Đền Thờ, đang ngồi giữa các thầy dạy, vừa nghe họ, vừa đặt câu hỏi.` },
  { slug: 'finding-hail-mary-4', ref: 'Lk 2:46', en: `And it came to pass, that, after three days, they found him in the temple, sitting in the midst of the doctors, hearing them, and asking them questions.`, vi: `Sau ba ngày, hai ông bà mới tìm thấy con trong Đền Thờ, đang ngồi giữa các thầy dạy, vừa nghe họ, vừa đặt câu hỏi.` },
  { slug: 'finding-hail-mary-5', ref: 'Lk 2:47', en: `And all that heard him were astonished at his wisdom and his answers.`, vi: `Ai nghe cậu nói cũng ngạc nhiên về trí thông minh và những lời đối đáp của cậu.` },
  { slug: 'finding-hail-mary-6', ref: 'Lk 2:48', en: `And seeing him, they wondered. And his mother said to him: Son, why hast thou done so to us? behold thy father and I have sought thee sorrowing.`, vi: `Khi thấy con, hai ông bà sửng sốt, và mẹ Người nói với Người: "Con ơi, sao con lại xử với cha mẹ như vậy? Con thấy không, cha con và mẹ đây đã phải cực lòng tìm con!"` },
  { slug: 'finding-hail-mary-7', ref: 'Lk 2:49', en: `And he said to them: How is it that you sought me? did you not know, that I must be about my father's business?`, vi: `Người đáp: "Sao cha mẹ lại tìm con? Cha mẹ không biết là con có bổn phận ở nhà của Cha con sao?"` },
  { slug: 'finding-hail-mary-8', ref: 'Lk 2:50', en: `And they understood not the word that he spoke unto them.`, vi: `Nhưng ông bà không hiểu lời Người vừa nói.` },
  { slug: 'finding-hail-mary-9', ref: 'Lk 2:51', en: `And he went down with them, and came to Nazareth, and was subject to them.`, vi: `Sau đó, Người đi xuống cùng với cha mẹ, trở về Na-da-rét và hằng vâng phục các ngài.` },
  { slug: 'finding-hail-mary-10', ref: 'Lk 2:51', en: `And his mother kept all these words in her heart.`, vi: `Riêng mẹ Người thì hằng ghi nhớ tất cả những điều ấy trong lòng.` },

  // ── Luminous: baptism (Mt 3:1-17) ──
  { slug: 'baptism-hail-mary-1', ref: 'Mt 3:1-2', en: `And in those days cometh John the Baptist preaching in the desert of Judea. And saying: Do penance: for the kingdom of heaven is at hand.`, vi: `Hồi ấy, ông Gio-an Tẩy Giả đến rao giảng trong hoang địa miền Giu-đê rằng: "Anh em hãy sám hối, vì Nước Trời đã đến gần."` },
  { slug: 'baptism-hail-mary-2', ref: 'Mt 3:5-6', en: `Then went out to him Jerusalem and all Judea, and all the country about Jordan: And were baptized by him in the Jordan, confessing their sins.`, vi: `Bấy giờ, người ta từ Giê-ru-sa-lem và khắp miền Giu-đê, cùng khắp vùng ven sông Gio-đan, kéo đến với ông. Họ thú tội, và ông làm phép rửa cho họ trong sông Gio-đan.` },
  { slug: 'baptism-hail-mary-3', ref: 'Mt 3:11', en: `but he that shall come after me, is mightier than I, whose shoes I am not worthy to bear;`, vi: `Còn Đấng đến sau tôi thì quyền thế hơn tôi, tôi không đáng xách dép cho Người.` },
  { slug: 'baptism-hail-mary-4', ref: 'Mt 3:11', en: `he shall baptize you in the Holy Ghost and fire.`, vi: `Người sẽ làm phép rửa cho các anh trong Thánh Thần và lửa.` },
  { slug: 'baptism-hail-mary-5', ref: 'Mt 3:13', en: `Then cometh Jesus from Galilee to the Jordan, unto John, to be baptized by him.`, vi: `Bấy giờ, Đức Giê-su từ miền Ga-li-lê đến sông Gio-đan, gặp ông Gio-an để xin ông làm phép rửa cho mình.` },
  { slug: 'baptism-hail-mary-6', ref: 'Mt 3:14', en: `But John stayed him, saying: I ought to be baptized by thee, and comest thou to me?`, vi: `Nhưng ông một mực can Người và nói: "Chính tôi mới cần được Ngài làm phép rửa, thế mà Ngài lại đến với tôi!"` },
  { slug: 'baptism-hail-mary-7', ref: 'Mt 3:15', en: `And Jesus answering, said to him: Suffer it to be so now. For so it becometh us to fulfil all justice. Then he suffered him.`, vi: `Nhưng Đức Giê-su trả lời: "Bây giờ cứ thế đã. Vì chúng ta nên làm như vậy để giữ trọn đức công chính." Bấy giờ ông Gio-an mới chiều theo ý Người.` },
  { slug: 'baptism-hail-mary-8', ref: 'Mt 3:16', en: `And Jesus being baptized, forthwith came out of the water: and lo, the heavens were opened to him:`, vi: `Khi Đức Giê-su chịu phép rửa xong, vừa ở dưới nước lên, thì các tầng trời mở ra.` },
  { slug: 'baptism-hail-mary-9', ref: 'Mt 3:16', en: `and he saw the Spirit of God descending as a dove, and coming upon him.`, vi: `Người thấy Thần Khí Thiên Chúa đáp xuống như chim bồ câu và ngự trên Người.` },
  { slug: 'baptism-hail-mary-10', ref: 'Mt 3:17', en: `And behold a voice from heaven, saying: This is my beloved Son, in whom I am well pleased.`, vi: `Và có tiếng từ trời phán: "Đây là Con yêu dấu của Ta, Ta hài lòng về Người."` },

  // ── Luminous: cana (Jn 2:1-11) ──
  { slug: 'cana-hail-mary-1', ref: 'Jn 2:1', en: `And the third day, there was a marriage in Cana of Galilee: and the mother of Jesus was there.`, vi: `Ngày thứ ba, có tiệc cưới tại Ca-na miền Ga-li-lê. Trong tiệc cưới có thân mẫu Đức Giê-su.` },
  { slug: 'cana-hail-mary-2', ref: 'Jn 2:3', en: `And the wine failing, the mother of Jesus saith to him: They have no wine.`, vi: `Khi thấy thiếu rượu, thân mẫu Đức Giê-su nói với Người: "Họ hết rượu rồi."` },
  { slug: 'cana-hail-mary-3', ref: 'Jn 2:4', en: `And Jesus saith to her: Woman, what is that to me and to thee? my hour is not yet come.`, vi: `Đức Giê-su đáp: "Thưa bà, chuyện đó can gì đến bà và tôi? Giờ của tôi chưa đến."` },
  { slug: 'cana-hail-mary-4', ref: 'Jn 2:5', en: `His mother saith to the waiters: Whatsoever he shall say to you, do ye.`, vi: `Thân mẫu Người nói với gia nhân: "Người bảo gì, các anh cứ việc làm theo."` },
  { slug: 'cana-hail-mary-5', ref: 'Jn 2:6', en: `Now there were set there six waterpots of stone, according to the manner of the purifying of the Jews, containing two or three measures apiece.`, vi: `Ở đó có đặt sáu chum đá dùng vào việc thanh tẩy theo thói tục người Do-thái, mỗi chum chứa được khoảng tám mươi hoặc một trăm hai mươi lít nước.` },
  { slug: 'cana-hail-mary-6', ref: 'Jn 2:7', en: `Jesus saith to them: Fill the waterpots with water. And they filled them up to the brim.`, vi: `Đức Giê-su bảo họ: "Các anh đổ đầy nước vào chum đi!" Và họ đổ đầy tới miệng.` },
  { slug: 'cana-hail-mary-7', ref: 'Jn 2:9', en: `And when the chief steward had tasted the water made wine, and knew not whence it was, but the waiters knew who had drawn the water; the chief steward calleth the bridegroom,`, vi: `Khi người quản tiệc nếm thử nước đã hoá thành rượu (mà không biết rượu từ đâu ra, còn gia nhân đã múc nước thì biết), ông mới gọi tân lang lại` },
  { slug: 'cana-hail-mary-8', ref: 'Jn 2:10', en: `And saith to him: Every man at first setteth forth good wine, and when men have well drunk, then that which is worse. But thou hast kept the good wine until now.`, vi: `và nói: "Ai ai cũng thết rượu ngon trước, và khi khách đã ngà ngà mới đãi rượu xoàng hơn. Còn anh, anh lại giữ rượu ngon mãi cho đến bây giờ."` },
  { slug: 'cana-hail-mary-9', ref: 'Jn 2:10', en: `And saith to him: Every man at first setteth forth good wine, and when men have well drunk, then that which is worse. But thou hast kept the good wine until now.`, vi: `và nói: "Ai ai cũng thết rượu ngon trước, và khi khách đã ngà ngà mới đãi rượu xoàng hơn. Còn anh, anh lại giữ rượu ngon mãi cho đến bây giờ."` },
  { slug: 'cana-hail-mary-10', ref: 'Jn 2:11', en: `This beginning of miracles did Jesus in Cana of Galilee; and manifested his glory, and his disciples believed in him.`, vi: `Đức Giê-su đã làm dấu lạ đầu tiên này tại Ca-na miền Ga-li-lê và bày tỏ vinh quang của Người. Các môn đệ đã tin vào Người.` },

  // ── Luminous: proclamation (Mk 1; Jn 3; Mt 5,10,18; Lk 4; Jn 18) ──
  { slug: 'proclamation-hail-mary-1', ref: 'Mk 1:14-15', en: `And after that John was delivered up, Jesus came into Galilee, preaching the gospel of the kingdom of God, And saying: The time is accomplished, and the kingdom of God is at hand: repent, and believe the gospel.`, vi: `Sau khi ông Gio-an bị nộp, Đức Giê-su đến miền Ga-li-lê rao giảng Tin Mừng của Thiên Chúa. Người nói: "Thời kỳ đã mãn, và Triều Đại Thiên Chúa đã đến gần. Anh em hãy sám hối và tin vào Tin Mừng."` },
  { slug: 'proclamation-hail-mary-2', ref: 'Jn 3:5', en: `Jesus answered: Amen, amen I say to thee, unless a man be born again of water and the Holy Ghost, he cannot enter into the kingdom of God.`, vi: `Đức Giê-su đáp: "Thật, tôi bảo thật ông: không ai có thể vào Nước Thiên Chúa, nếu không sinh ra bởi nước và Thần Khí."` },
  { slug: 'proclamation-hail-mary-3', ref: 'Mt 5:3', en: `Blessed are the poor in spirit: for theirs is the kingdom of heaven.`, vi: `"Phúc thay ai có tâm hồn nghèo khó, vì Nước Trời là của họ.` },
  { slug: 'proclamation-hail-mary-4', ref: 'Mt 5:10', en: `Blessed are they that suffer persecution for justice' sake: for theirs is the kingdom of heaven.`, vi: `Phúc thay ai bị bách hại vì sống công chính, vì Nước Trời là của họ.` },
  { slug: 'proclamation-hail-mary-5', ref: 'Mt 5:20', en: `For I tell you, that unless your justice abound more than that of the scribes and Pharisees, you shall not enter into the kingdom of heaven.`, vi: `Vậy, Thầy bảo cho anh em biết, nếu anh em không ăn ở công chính hơn các kinh sư và người Pha-ri-sêu, thì sẽ chẳng được vào Nước Trời.` },
  { slug: 'proclamation-hail-mary-6', ref: 'Mt 10:7', en: `And going, preach, saying: The kingdom of heaven is at hand.`, vi: `Dọc đường hãy rao giảng rằng: Nước Trời đã đến gần.` },
  { slug: 'proclamation-hail-mary-7', ref: 'Mt 18:3', en: `And said: Amen I say to you, unless you be converted, and become as little children, you shall not enter into the kingdom of heaven.`, vi: `và bảo: "Thầy bảo thật anh em: nếu anh em không trở lại mà nên như trẻ nhỏ, thì sẽ chẳng được vào Nước Trời."` },
  { slug: 'proclamation-hail-mary-8', ref: 'Lk 4:43', en: `But he said to them: To other cities also I must preach the kingdom of God: for therefore am I sent.`, vi: `Nhưng Người nói với họ: "Tôi còn phải loan báo Tin Mừng Nước Thiên Chúa cho các thành khác nữa, vì tôi được sai đi cốt để làm việc đó."` },
  { slug: 'proclamation-hail-mary-9', ref: 'Lk 4:43', en: `But he said to them: To other cities also I must preach the kingdom of God: for therefore am I sent.`, vi: `Nhưng Người nói với họ: "Tôi còn phải loan báo Tin Mừng Nước Thiên Chúa cho các thành khác nữa, vì tôi được sai đi cốt để làm việc đó."` },
  { slug: 'proclamation-hail-mary-10', ref: 'Jn 18:36', en: `Jesus answered: My kingdom is not of this world. If my kingdom were of this world, my servants would certainly strive that I should not be delivered to the Jews: but now my kingdom is not from hence.`, vi: `Đức Giê-su trả lời: "Nước tôi không thuộc về thế gian này. Nếu Nước tôi thuộc về thế gian này, thuộc hạ của tôi đã chiến đấu không để tôi bị nộp cho người Do-thái. Nhưng thật ra Nước tôi không thuộc chốn này."` },

  // ── Luminous: transfiguration (Mt 17:1-7; Lk 9:32; Mk 9:8) ──
  { slug: 'transfiguration-hail-mary-1', ref: 'Mt 17:1', en: `And after six days Jesus taketh unto him Peter and James, and John his brother, and bringeth them up into a high mountain apart:`, vi: `Sáu ngày sau, Đức Giê-su đem các ông Phê-rô, Gia-cô-bê và Gio-an là em ông Gia-cô-bê đi theo mình. Người đưa các ông đi riêng ra một chỗ, tới một ngọn núi cao.` },
  { slug: 'transfiguration-hail-mary-2', ref: 'Mt 17:2', en: `And he was transfigured before them. And his face did shine as the sun: and his garments became white as snow.`, vi: `Rồi Người biến đổi hình dạng trước mặt các ông. Dung nhan Người chói lọi như mặt trời, và y phục Người trở nên trắng tinh như ánh sáng.` },
  { slug: 'transfiguration-hail-mary-3', ref: 'Mt 17:3', en: `And behold there appeared to them Moses and Elias talking with him.`, vi: `Và bỗng các ông thấy ông Mô-sê và ông Ê-li-a hiện ra đàm đạo với Người.` },
  { slug: 'transfiguration-hail-mary-4', ref: 'Lk 9:32', en: `But Peter and they that were with him were heavy with sleep. And waking, they saw his glory, and the two men that stood with him.`, vi: `Còn ông Phê-rô và đồng bạn thì ngủ mê mệt, nhưng khi tỉnh hẳn, các ông nhìn thấy vinh quang của Đức Giê-su, và hai nhân vật đứng bên Người.` },
  { slug: 'transfiguration-hail-mary-5', ref: 'Mt 17:4', en: `And Peter answering, said to Jesus: Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles, one for thee, and one for Moses, and one for Elias.`, vi: `Bấy giờ ông Phê-rô thưa với Đức Giê-su rằng: "Lạy Ngài, chúng con ở đây, thật là hay! Nếu Ngài muốn, con xin dựng tại đây ba cái lều, một cho Ngài, một cho ông Mô-sê, và một cho ông Ê-li-a."` },
  { slug: 'transfiguration-hail-mary-6', ref: 'Mt 17:5', en: `And as he was yet speaking, behold a bright cloud overshadowed them. And lo, a voice out of the cloud, saying: This is my beloved Son, in whom I am well pleased: hear ye him.`, vi: `Ông còn đang nói, chợt có đám mây sáng ngời bao phủ các ông, và có tiếng từ đám mây phán rằng: "Đây là Con yêu dấu của Ta, Ta hài lòng về Người. Các ngươi hãy vâng nghe lời Người!"` },
  { slug: 'transfiguration-hail-mary-7', ref: 'Mt 17:6', en: `And the disciples hearing, fell upon their face, and were very much afraid.`, vi: `Nghe vậy, các môn đệ kinh hoàng, ngã sấp mặt xuống đất.` },
  { slug: 'transfiguration-hail-mary-8', ref: 'Mt 17:7', en: `And Jesus came and touched them: and said to them, Arise, and fear not.`, vi: `Bấy giờ Đức Giê-su lại gần, chạm vào các ông và bảo: "Chỗi dậy đi, đừng sợ!"` },
  { slug: 'transfiguration-hail-mary-9', ref: 'Mt 17:7', en: `And Jesus came and touched them: and said to them, Arise, and fear not.`, vi: `Bấy giờ Đức Giê-su lại gần, chạm vào các ông và bảo: "Chỗi dậy đi, đừng sợ!"` },
  { slug: 'transfiguration-hail-mary-10', ref: 'Mk 9:8', en: `And immediately looking about, they saw no man any more, but Jesus only with them.`, vi: `Các ông chợt nhìn quanh, thì không thấy ai nữa, chỉ còn Đức Giê-su với các ông mà thôi.` },

  // ── Luminous: institution (Jn 6; Mt 26; Lk 22; 1 Cor 11) ──
  { slug: 'institution-hail-mary-1', ref: 'Jn 6:35', en: `And Jesus said to them: I am the bread of life: he that cometh to me shall not hunger: and he that believeth in me shall never thirst.`, vi: `Đức Giê-su bảo họ: "Chính tôi là bánh trường sinh. Ai đến với tôi, không hề phải đói; ai tin vào tôi, chẳng khát bao giờ!"` },
  { slug: 'institution-hail-mary-2', ref: 'Jn 6:35', en: `And Jesus said to them: I am the bread of life: he that cometh to me shall not hunger: and he that believeth in me shall never thirst.`, vi: `Đức Giê-su bảo họ: "Chính tôi là bánh trường sinh. Ai đến với tôi, không hề phải đói; ai tin vào tôi, chẳng khát bao giờ!"` },
  { slug: 'institution-hail-mary-3', ref: 'Jn 6:54', en: `He that eateth my flesh, and drinketh my blood, hath everlasting life: and I will raise him up in the last day.`, vi: `Ai ăn thịt và uống máu tôi, thì được sống muôn đời, và tôi sẽ cho người ấy sống lại vào ngày sau hết,` },
  { slug: 'institution-hail-mary-4', ref: 'Jn 6:56', en: `He that eateth my flesh, and drinketh my blood, abideth in me: and I in him.`, vi: `Ai ăn thịt và uống máu tôi, thì ở lại trong tôi, và tôi ở lại trong người ấy.` },
  { slug: 'institution-hail-mary-5', ref: 'Mt 26:26', en: `And whilst they were at supper, Jesus took bread, and blessed, and broke: and gave to his disciples, and said: Take ye, and eat. This is my body.`, vi: `Cũng trong bữa ăn, Đức Giê-su cầm lấy bánh, dâng lời chúc tụng, rồi bẻ ra, trao cho môn đệ và nói: "Anh em cầm lấy mà ăn, đây là mình Thầy."` },
  { slug: 'institution-hail-mary-6', ref: 'Lk 22:19', en: `And taking bread, he gave thanks, and brake; and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me.`, vi: `Rồi Người cầm lấy bánh, dâng lời tạ ơn, bẻ ra, trao cho các ông và nói: "Đây là mình Thầy, hiến tế vì anh em. Anh em hãy làm việc này, mà tưởng nhớ đến Thầy."` },
  { slug: 'institution-hail-mary-7', ref: 'Mt 26:27-28', en: `And taking the chalice, he gave thanks, and gave to them, saying: Drink ye all of this. For this is my blood of the new testament, which shall be shed for many unto remission of sins.`, vi: `Rồi Người cầm lấy chén, dâng lời tạ ơn, trao cho môn đệ và nói: "Tất cả anh em hãy uống chén này, vì đây là máu Thầy, máu Giao Ước, đổ ra cho muôn người được tha tội."` },
  { slug: 'institution-hail-mary-8', ref: '1 Cor 11:25', en: `In like manner also the chalice, after he had supped, saying: This chalice is the new testament in my blood: this do ye, as often as you shall drink, for the commemoration of me.`, vi: `Cũng thế, cuối bữa ăn, Người nâng chén và nói: "Đây là chén Máu Thầy, Máu đổ ra để lập Giao Ước Mới; mỗi khi uống, anh em hãy làm như Thầy vừa làm để tưởng nhớ đến Thầy."` },
  { slug: 'institution-hail-mary-9', ref: '1 Cor 11:25', en: `In like manner also the chalice, after he had supped, saying: This chalice is the new testament in my blood: this do ye, as often as you shall drink, for the commemoration of me.`, vi: `Cũng thế, cuối bữa ăn, Người nâng chén và nói: "Đây là chén Máu Thầy, Máu đổ ra để lập Giao Ước Mới; mỗi khi uống, anh em hãy làm như Thầy vừa làm để tưởng nhớ đến Thầy."` },
  { slug: 'institution-hail-mary-10', ref: '1 Cor 11:26', en: `For as often as you shall eat this bread, and drink the chalice, you shall shew the death of the Lord, until he come.`, vi: `Thật vậy, cho tới ngày Chúa đến, mỗi lần ăn Bánh và uống Chén này, là anh em loan truyền Chúa đã chịu chết.` },

  // ── Sorrowful: agony (Mt 26:36-39; Lk 22:43-48) ──
  { slug: 'agony-hail-mary-1', ref: 'Mt 26:36-37', en: `Then Jesus came with them into a country place which is called Gethsemani; and he said to his disciples: Sit you here, till I go yonder and pray. And taking with him Peter and the two sons of Zebedee, he began to grow sorrowful and to be sad.`, vi: `Bấy giờ Đức Giê-su đi cùng với các ông đến một thửa đất gọi là Ghết-sê-ma-ni. Người nói với các môn đệ: "Anh em ngồi lại đây, Thầy đến đàng kia cầu nguyện." Rồi Người đưa ông Phê-rô và hai người con ông Dê-bê-đê đi theo. Người bắt đầu cảm thấy buồn rầu xao xuyến.` },
  { slug: 'agony-hail-mary-2', ref: 'Mt 26:38', en: `Then he saith to them: My soul is sorrowful even unto death: stay you here, and watch with me.`, vi: `Bấy giờ Người nói với các ông: "Tâm hồn Thầy buồn đến chết được. Anh em ở lại đây mà canh thức với Thầy."` },
  { slug: 'agony-hail-mary-3', ref: 'Mt 26:39', en: `And going a little further, he fell upon his face, praying, and saying: My Father, if it be possible, let this chalice pass from me. Nevertheless not as I will, but as thou wilt.`, vi: `Người đi xa hơn một chút, sấp mặt xuống, cầu nguyện rằng: "Lạy Cha, nếu có thể được, xin cho con khỏi phải uống chén này. Tuy vậy, xin đừng theo ý con, mà xin theo ý Cha."` },
  { slug: 'agony-hail-mary-4', ref: 'Mt 26:39', en: `And going a little further, he fell upon his face, praying, and saying: My Father, if it be possible, let this chalice pass from me. Nevertheless not as I will, but as thou wilt.`, vi: `Người đi xa hơn một chút, sấp mặt xuống, cầu nguyện rằng: "Lạy Cha, nếu có thể được, xin cho con khỏi phải uống chén này. Tuy vậy, xin đừng theo ý con, mà xin theo ý Cha."` },
  { slug: 'agony-hail-mary-5', ref: 'Lk 22:43', en: `And there appeared to him an angel from heaven, strengthening him.`, vi: `Bấy giờ có thiên sứ tự trời hiện đến tăng sức cho Người.` },
  { slug: 'agony-hail-mary-6', ref: 'Lk 22:44', en: `And being in an agony, he prayed the longer.`, vi: `Người lâm cơn xao xuyến bồi hồi, nên càng khẩn thiết cầu xin.` },
  { slug: 'agony-hail-mary-7', ref: 'Lk 22:44', en: `And his sweat became as drops of blood, trickling down upon the ground.`, vi: `Và mồ hôi Người như những giọt máu rơi xuống đất.` },
  { slug: 'agony-hail-mary-8', ref: 'Lk 22:45', en: `And when he rose up from prayer, and was come to his disciples, he found them sleeping for sorrow.`, vi: `Cầu nguyện xong, Người đứng lên, đến chỗ các môn đệ, thấy các ông đang ngủ vì buồn phiền,` },
  { slug: 'agony-hail-mary-9', ref: 'Lk 22:47', en: `As he was yet speaking, behold a multitude; and he that was called Judas, one of the twelve, went before them, and drew near to Jesus, for to kiss him.`, vi: `Người còn đang nói, thì một đám đông xuất hiện, và kẻ dẫn đầu tên là Giu-đa, một người trong Nhóm Mười Hai. Hắn lại gần Đức Giê-su để hôn Người.` },
  { slug: 'agony-hail-mary-10', ref: 'Lk 22:48', en: `And Jesus said to him: Judas, dost thou betray the Son of man with a kiss?`, vi: `Đức Giê-su bảo hắn: "Giu-đa ơi, anh dùng cái hôn mà nộp Con Người sao?"` },

  // ── Sorrowful: scourging (Mk 15:1; Jn 18:33-37; Lk 23:22; Is 53:3-5,7) ──
  { slug: 'scourging-hail-mary-1', ref: 'Mk 15:1', en: `And straightway in the morning, the chief priests holding a consultation with the ancients and the scribes and the whole council, binding Jesus, led him away, and delivered him to Pilate.`, vi: `Vừa tảng sáng, các thượng tế đã họp bàn với các kỳ mục và kinh sư, tức là toàn thể Thượng Hội Đồng. Sau đó, họ trói Đức Giê-su lại và giải đi nộp cho ông Phi-la-tô.` },
  { slug: 'scourging-hail-mary-2', ref: 'Jn 18:33', en: `Pilate therefore went into the hall again, and called Jesus, and said to him: Art thou the king of the Jews?`, vi: `Ông Phi-la-tô trở vào dinh, cho gọi Đức Giê-su và nói với Người: "Ông có phải là vua dân Do-thái không?"` },
  { slug: 'scourging-hail-mary-3', ref: 'Jn 18:36', en: `Jesus answered: My kingdom is not of this world. If my kingdom were of this world, my servants would certainly strive that I should not be delivered to the Jews: but now my kingdom is not from hence.`, vi: `Đức Giê-su trả lời: "Nước tôi không thuộc về thế gian này. Nếu Nước tôi thuộc về thế gian này, thuộc hạ của tôi đã chiến đấu không để tôi bị nộp cho người Do-thái. Nhưng thật ra Nước tôi không thuộc chốn này."` },
  { slug: 'scourging-hail-mary-4', ref: 'Jn 18:37', en: `Pilate therefore said to him: Art thou a king then? Jesus answered: Thou sayest that I am a king. For this was I born, and for this came I into the world; that I should give testimony to the truth. Every one that is of the truth, heareth my voice.`, vi: `Ông Phi-la-tô liền hỏi: "Vậy ông là vua sao?" Đức Giê-su đáp: "Chính ngài nói rằng tôi là vua. Tôi đã sinh ra và đã đến thế gian nhằm mục đích này: làm chứng cho sự thật. Ai đứng về phía sự thật thì nghe tiếng tôi."` },
  { slug: 'scourging-hail-mary-5', ref: 'Lk 23:22', en: `And he said to them the third time: Why, what evil hath this man done? I find no cause of death in him. I will chastise him therefore, and let him go.`, vi: `Lần thứ ba, ông Phi-la-tô nói với họ: "Nhưng ông ấy đã làm điều gì gian ác? Ta xét thấy ông ấy không có tội gì đáng chết. Vậy ta sẽ cho đánh đòn rồi thả ra."` },
  { slug: 'scourging-hail-mary-6', ref: 'Is 53:3', en: `Despised, and the most abject of men, a man of sorrows, and acquainted with infirmity: and his look was as it were hidden and despised, whereupon we esteemed him not.`, vi: `Người bị đời khinh khi ruồng rẫy, phải đau khổ triền miên và nếm mùi bệnh tật. Người như kẻ ai thấy cũng che mặt không nhìn, bị chúng ta khinh khi, không đếm xỉa tới.` },
  { slug: 'scourging-hail-mary-7', ref: 'Is 53:7', en: `He was offered because it was his own will, and he opened not his mouth: he shall be led as a sheep to the slaughter, and shall be dumb as a lamb before his shearer, and he shall not open his mouth.`, vi: `Bị ngược đãi, người cam chịu nhục, chẳng mở miệng kêu ca; như chiên bị đem đi làm thịt, như cừu câm nín khi bị xén lông, người chẳng hề mở miệng.` },
  { slug: 'scourging-hail-mary-8', ref: 'Is 53:4', en: `Surely he hath borne our infirmities and carried our sorrows: and we have thought him as it were a leper, and as one struck by God and afflicted.`, vi: `Sự thật, chính người đã mang lấy những bệnh tật của chúng ta, đã gánh chịu những đau khổ của chúng ta, còn chúng ta, chúng ta lại tưởng người bị phạt, bị Thiên Chúa giáng hoạ, phải nhục nhã ê chề.` },
  { slug: 'scourging-hail-mary-9', ref: 'Is 53:5', en: `But he was wounded for our iniquities, he was bruised for our sins: the chastisement of our peace was upon him,`, vi: `Chính người đã bị đâm vì chúng ta phạm tội, bị nghiền nát vì chúng ta lỗi lầm; người đã chịu sửa trị để chúng ta được bình an,` },
  { slug: 'scourging-hail-mary-10', ref: 'Is 53:5', en: `and by his bruises we are healed.`, vi: `đã phải mang thương tích cho chúng ta được chữa lành.` },

  // ── Sorrowful: crowning (Mk 15:15-19; Mt 27:24; Jn 19:5,14-15) ──
  { slug: 'crowning-hail-mary-1', ref: 'Mk 15:16-17', en: `And the soldiers led him away into the court of the palace, and they called together the whole band: And they clothe him with purple, and platting a crown of thorns, they put it upon him.`, vi: `Lính điệu Đức Giê-su vào bên trong công trường, tức là dinh tổng trấn, và tập trung cả cơ đội lại. Chúng khoác cho Người một tấm áo điều, và kết một vòng gai làm vương miện đặt lên đầu Người.` },
  { slug: 'crowning-hail-mary-2', ref: 'Mk 15:17', en: `And they clothe him with purple, and platting a crown of thorns, they put it upon him.`, vi: `Chúng khoác cho Người một tấm áo điều, và kết một vòng gai làm vương miện đặt lên đầu Người.` },
  { slug: 'crowning-hail-mary-3', ref: 'Mk 15:18', en: `And they began to salute him: Hail, king of the Jews.`, vi: `Rồi chúng bái chào Người: "Vạn tuế đức vua dân Do-thái!"` },
  { slug: 'crowning-hail-mary-4', ref: 'Mk 15:19', en: `And they struck his head with a reed: and they did spit on him. And bowing their knees, they adored him.`, vi: `Chúng lấy cây sậy đập lên đầu Người, khạc nhổ vào Người, và quỳ gối bái lạy.` },
  { slug: 'crowning-hail-mary-5', ref: 'Mt 27:24', en: `And Pilate seeing that he prevailed nothing, but that rather a tumult was made; taking water washed his hands before the people, saying: I am innocent of the blood of this just man; look you to it.`, vi: `Tổng trấn Phi-la-tô thấy đã chẳng được ích gì mà còn thêm náo động, nên lấy nước rửa tay trước mặt đám đông mà nói: "Ta vô can trong vụ đổ máu người này. Mặc các người liệu lấy!"` },
  { slug: 'crowning-hail-mary-6', ref: 'Jn 19:5', en: `(Jesus therefore came forth, bearing the crown of thorns and the purple garment.) And he saith to them: Behold the Man.`, vi: `Vậy, Đức Giê-su bước ra ngoài, đầu đội vương miện bằng gai, mình khoác áo choàng đỏ. Ông Phi-la-tô nói với họ: "Đây là người!"` },
  { slug: 'crowning-hail-mary-7', ref: 'Jn 19:14-15', en: `And it was the parasceve of the pasch, about the sixth hour, and he saith to the Jews: Behold your king. But they cried out: Away with him; away with him; crucify him.`, vi: `Hôm ấy là ngày áp lễ Vượt Qua, vào khoảng mười hai giờ trưa. Ông Phi-la-tô nói với người Do-thái: "Đây là vua các người!" Họ liền hô lớn: "Đem đi! Đem nó đi! Đóng đinh nó vào thập giá!"` },
  { slug: 'crowning-hail-mary-8', ref: 'Jn 19:15', en: `Pilate saith to them: Shall I crucify your king?`, vi: `Ông Phi-la-tô nói với họ: "Chẳng lẽ ta lại đóng đinh vua các người sao?"` },
  { slug: 'crowning-hail-mary-9', ref: 'Jn 19:15', en: `The chief priests answered: We have no king but Caesar.`, vi: `Các thượng tế đáp: "Chúng tôi không có vua nào cả, ngoài Xê-da."` },
  { slug: 'crowning-hail-mary-10', ref: 'Mk 15:15', en: `And so Pilate being willing to satisfy the people, released to them Barabbas, and delivered up Jesus, when he had scourged him, to be crucified.`, vi: `Vì muốn chiều lòng đám đông, ông Phi-la-tô phóng thích tên Ba-ra-ba, truyền đánh đòn Đức Giê-su, rồi trao Người cho họ đóng đinh vào thập giá.` },

  // ── Sorrowful: carrying (Lk 9:23-24; Jn 19:17; Mt 11:29-30; Rom 8:18; Lk 23:26-28; Gal 6:14) ──
  { slug: 'carrying-hail-mary-1', ref: 'Lk 9:23', en: `And he said to all: If any man will come after me, let him deny himself, and take up his cross daily, and follow me.`, vi: `Rồi Đức Giê-su nói với mọi người: "Ai muốn theo tôi, phải từ bỏ chính mình, vác thập giá mình hằng ngày mà theo."` },
  { slug: 'carrying-hail-mary-2', ref: 'Jn 19:17', en: `And bearing his own cross, he went forth to that place which is called Calvary, but in Hebrew Golgotha.`, vi: `Chính Người vác lấy thập giá đi ra, đến nơi gọi là Cái Sọ, tiếng Híp-ri là Gôn-gô-tha;` },
  { slug: 'carrying-hail-mary-3', ref: 'Lk 9:24', en: `For whosoever will save his life, shall lose it; for he that shall lose his life for my sake, shall save it.`, vi: `Quả vậy, ai muốn cứu mạng sống mình, thì sẽ mất; còn ai liều mất mạng sống mình vì tôi, thì sẽ cứu được mạng sống ấy.` },
  { slug: 'carrying-hail-mary-4', ref: 'Mt 11:29', en: `Take up my yoke upon you, and learn of me, because I am meek, and humble of heart: and you shall find rest to your souls.`, vi: `Anh em hãy mang lấy ách của tôi, và hãy học với tôi, vì tôi có lòng hiền hậu và khiêm nhường. Tâm hồn anh em sẽ được nghỉ ngơi bồi dưỡng.` },
  { slug: 'carrying-hail-mary-5', ref: 'Mt 11:30', en: `For my yoke is sweet and my burden light.`, vi: `Vì ách tôi êm ái, và gánh tôi nhẹ nhàng."` },
  { slug: 'carrying-hail-mary-6', ref: 'Rom 8:18', en: `For I reckon that the sufferings of this time are not worthy to be compared with the glory to come, that shall be revealed in us.`, vi: `Thật vậy, tôi nghĩ rằng: những đau khổ chúng ta chịu bây giờ sánh sao được với vinh quang mà Thiên Chúa sẽ mặc khải nơi chúng ta.` },
  { slug: 'carrying-hail-mary-7', ref: 'Lk 23:26', en: `And as they led him away, they laid hold of one Simon of Cyrene, coming from the country; and they laid the cross on him to carry after Jesus.`, vi: `Khi điệu Đức Giê-su đi, họ bắt một người từ miền quê lên, tên là Si-môn, gốc Ky-rê-nê, đặt thập giá lên vai cho ông vác theo sau Đức Giê-su.` },
  { slug: 'carrying-hail-mary-8', ref: 'Lk 23:27', en: `And there followed him a great multitude of people, and of women, who bewailed and lamented him.`, vi: `Dân chúng đi theo Người đông lắm, trong số đó có nhiều phụ nữ vừa đấm ngực vừa than khóc Người.` },
  { slug: 'carrying-hail-mary-9', ref: 'Lk 23:28', en: `But Jesus turning to them, said: Daughters of Jerusalem, weep not over me; but weep for yourselves, and for your children.`, vi: `Đức Giê-su quay lại phía các bà mà nói: "Hỡi chị em thành Giê-ru-sa-lem, đừng khóc thương tôi làm gì. Có khóc thì khóc cho phận mình và cho con cháu."` },
  { slug: 'carrying-hail-mary-10', ref: 'Gal 6:14', en: `But God forbid that I should glory, save in the cross of our Lord Jesus Christ; by whom the world is crucified to me, and I to the world.`, vi: `Ước chi tôi chẳng hãnh diện về điều gì, ngoài thập giá Đức Giê-su Ki-tô, Chúa chúng ta! Nhờ thập giá Người, thế gian đã bị đóng đinh vào thập giá đối với tôi, và tôi đối với thế gian.` },

  // ── Sorrowful: crucifixion (Lk 23:33-46; Jn 19:25-30; Jn 15:13) ──
  { slug: 'crucifixion-hail-mary-1', ref: 'Lk 23:33', en: `And when they were come to the place which is called Calvary, they crucified him there; and the robbers, one on the right hand, and the other on the left.`, vi: `Khi đến nơi gọi là "Đồi Sọ", họ đóng đinh Người vào thập giá, cùng lúc với hai tên gian phi, một tên bên phải, một tên bên trái.` },
  { slug: 'crucifixion-hail-mary-2', ref: 'Lk 23:34', en: `And Jesus said: Father, forgive them, for they know not what they do.`, vi: `Bấy giờ Đức Giê-su cầu nguyện rằng: "Lạy Cha, xin tha cho họ, vì họ không biết việc họ làm."` },
  { slug: 'crucifixion-hail-mary-3', ref: 'Jn 19:25', en: `Now there stood by the cross of Jesus, his mother, and his mother's sister, Mary of Cleophas, and Mary Magdalen.`, vi: `Đứng gần thập giá Đức Giê-su, có thân mẫu Người, chị của thân mẫu, bà Ma-ri-a vợ ông Cơ-lô-pát, cùng với bà Ma-ri-a Mác-đa-la.` },
  { slug: 'crucifixion-hail-mary-4', ref: 'Jn 19:26', en: `When Jesus therefore had seen his mother and the disciple standing whom he loved, he saith to his mother: Woman, behold thy son.`, vi: `Khi thấy thân mẫu và môn đệ mình thương mến đứng bên cạnh, Đức Giê-su nói với thân mẫu rằng: "Thưa Bà, đây là con của Bà."` },
  { slug: 'crucifixion-hail-mary-5', ref: 'Jn 19:27', en: `After that, he saith to the disciple: Behold thy mother. And from that hour, the disciple took her to his own.`, vi: `Rồi Người nói với môn đệ: "Đây là mẹ của anh." Kể từ giờ đó, người môn đệ rước bà về nhà mình.` },
  { slug: 'crucifixion-hail-mary-6', ref: 'Lk 23:44', en: `And it was almost the sixth hour; and there was darkness over all the earth until the ninth hour.`, vi: `Bấy giờ đã gần tới giờ thứ sáu, thế mà bóng tối bao phủ khắp mặt đất, mãi đến giờ thứ chín.` },
  { slug: 'crucifixion-hail-mary-7', ref: 'Jn 19:30', en: `Jesus therefore, when he had taken the vinegar, said: It is consummated.`, vi: `Nhắp xong, Đức Giê-su nói: "Thế là đã hoàn tất!"` },
  { slug: 'crucifixion-hail-mary-8', ref: 'Lk 23:46', en: `And Jesus crying out with a loud voice, said: Father, into thy hands I commend my spirit. And saying this, he gave up the ghost.`, vi: `Đức Giê-su kêu lớn tiếng: "Lạy Cha, con xin phó thác hồn con trong tay Cha." Nói xong, Người tắt thở.` },
  { slug: 'crucifixion-hail-mary-9', ref: 'Jn 19:30', en: `And bowing his head, he gave up the ghost.`, vi: `Rồi Người gục đầu xuống và trao Thần Khí.` },
  { slug: 'crucifixion-hail-mary-10', ref: 'Jn 15:13', en: `Greater love than this no man hath, that a man lay down his life for his friends.`, vi: `Không có tình thương nào cao cả hơn tình thương của người đã hy sinh tính mạng vì bạn hữu của mình.` },

  // ── Glorious: resurrection (Jn 16:20,22; Lk 24:1; Mt 28:2-8; Jn 11:25-26) ──
  { slug: 'resurrection-hail-mary-1', ref: 'Jn 16:20', en: `Amen, amen I say to you, that you shall lament and weep, but the world shall rejoice; and you shall be made sorrowful, but your sorrow shall be turned into joy.`, vi: `Thật, Thầy bảo thật anh em: anh em sẽ khóc lóc và than van, còn thế gian sẽ vui mừng. Anh em sẽ lo buồn, nhưng nỗi buồn của anh em sẽ trở thành niềm vui.` },
  { slug: 'resurrection-hail-mary-2', ref: 'Jn 16:22', en: `So also you now indeed have sorrow; but I will see you again, and your heart shall rejoice; and your joy no man shall take from you.`, vi: `Anh em cũng vậy, bây giờ anh em lo buồn, nhưng Thầy sẽ gặp lại anh em, lòng anh em sẽ vui mừng; và niềm vui của anh em, không ai lấy mất được.` },
  { slug: 'resurrection-hail-mary-3', ref: 'Lk 24:1', en: `And on the first day of the week, very early in the morning, they came to the sepulchre, bringing the spices which they had prepared.`, vi: `Ngày thứ nhất trong tuần, vừa tảng sáng, các bà đi ra mộ, mang theo dầu thơm đã chuẩn bị sẵn.` },
  { slug: 'resurrection-hail-mary-4', ref: 'Mt 28:2', en: `And behold there was a great earthquake. For an angel of the Lord descended from heaven, and coming, rolled back the stone, and sat upon it.`, vi: `Thình lình, đất rung chuyển dữ dội: thiên thần Chúa từ trời xuống, đến lăn tảng đá ra, rồi ngồi lên trên;` },
  { slug: 'resurrection-hail-mary-5', ref: 'Mt 28:5-6', en: `And the angel answering, said to the women: Fear not you; for I know that you seek Jesus who was crucified. He is not here, for he is risen, as he said.`, vi: `Thiên thần lên tiếng bảo các phụ nữ: "Này các bà, các bà đừng sợ! Tôi biết các bà tìm Đức Giê-su, Đấng bị đóng đinh. Người không có ở đây, vì Người đã trỗi dậy như Người đã nói."` },
  { slug: 'resurrection-hail-mary-6', ref: 'Mt 28:6', en: `Come, and see the place where the Lord was laid.`, vi: `Các bà đến mà xem chỗ Người đã nằm,` },
  { slug: 'resurrection-hail-mary-7', ref: 'Mt 28:7', en: `And going quickly, tell ye his disciples that he is risen: and behold he will go before you into Galilee; there you shall see him. Lo, I have foretold it to you.`, vi: `rồi mau về nói với môn đệ Người như thế này: Người đã trỗi dậy từ cõi chết, và Người đi Ga-li-lê trước các ông. Ở đó, các ông sẽ được thấy Người. Đấy, tôi xin nói cho các bà hay.` },
  { slug: 'resurrection-hail-mary-8', ref: 'Mt 28:8', en: `And they went out quickly from the sepulchre with fear and great joy, running to tell his disciples.`, vi: `Các bà vội vã rời khỏi mộ, tuy sợ hãi nhưng cũng rất đỗi vui mừng, chạy về báo tin cho môn đệ Đức Giê-su hay.` },
  { slug: 'resurrection-hail-mary-9', ref: 'Jn 11:25', en: `Jesus said to her: I am the resurrection and the life: he that believeth in me, although he be dead, shall live:`, vi: `Đức Giê-su liền phán: "Chính Thầy là sự sống lại và là sự sống. Ai tin vào Thầy, thì dù đã chết, cũng sẽ được sống."` },
  { slug: 'resurrection-hail-mary-10', ref: 'Jn 11:26', en: `And every one that liveth, and believeth in me, shall not die for ever. Believest thou this?`, vi: `Ai sống và tin vào Thầy, sẽ không bao giờ phải chết. Chị có tin thế không?"` },

  // ── Glorious: ascension (Lk 24:50-51; Mt 28:18-20; Mk 16:16,19; Acts 1:9) ──
  { slug: 'ascension-hail-mary-1', ref: 'Lk 24:50', en: `And he led them out as far as Bethania: and lifting up his hands, he blessed them.`, vi: `Sau đó, Người dẫn các ông tới gần Bê-ta-ni-a, rồi giơ tay chúc lành cho các ông.` },
  { slug: 'ascension-hail-mary-2', ref: 'Lk 24:51', en: `And it came to pass, whilst he blessed them, he departed from them, and was carried up to heaven.`, vi: `Và đang khi chúc lành, thì Người rời khỏi các ông và được đem lên trời.` },
  { slug: 'ascension-hail-mary-3', ref: 'Mt 28:18', en: `And Jesus coming, spoke to them, saying: All power is given to me in heaven and in earth.`, vi: `Đức Giê-su đến gần, nói với các ông: "Thầy đã được trao toàn quyền trên trời dưới đất."` },
  { slug: 'ascension-hail-mary-4', ref: 'Mt 28:19', en: `Going therefore, teach ye all nations; baptizing them in the name of the Father, and of the Son, and of the Holy Ghost.`, vi: `Vậy anh em hãy đi và làm cho muôn dân trở thành môn đệ, làm phép rửa cho họ nhân danh Chúa Cha, Chúa Con và Chúa Thánh Thần,` },
  { slug: 'ascension-hail-mary-5', ref: 'Mt 28:20', en: `Teaching them to observe all things whatsoever I have commanded you:`, vi: `dạy bảo họ tuân giữ mọi điều Thầy đã truyền cho anh em.` },
  { slug: 'ascension-hail-mary-6', ref: 'Mk 16:16', en: `He that believeth and is baptized, shall be saved:`, vi: `Ai tin và chịu phép rửa, sẽ được cứu độ;` },
  { slug: 'ascension-hail-mary-7', ref: 'Mk 16:16', en: `but he that believeth not shall be condemned.`, vi: `còn ai không tin, thì sẽ bị kết án."` },
  { slug: 'ascension-hail-mary-8', ref: 'Mt 28:20', en: `and behold I am with you all days, even to the consummation of the world.`, vi: `Và đây, Thầy ở cùng anh em mọi ngày cho đến tận thế."` },
  { slug: 'ascension-hail-mary-9', ref: 'Acts 1:9', en: `And when he had said these things, while they looked on, he was raised up: and a cloud received him out of their sight.`, vi: `Nói xong, Người được cất lên ngay trước mắt các ông, và có đám mây quyện lấy Người, khiến các ông không còn thấy Người nữa.` },
  { slug: 'ascension-hail-mary-10', ref: 'Mk 16:19', en: `And the Lord Jesus, after he had spoken to them, was taken up into heaven, and sitteth on the right hand of God.`, vi: `Nói xong, Chúa Giê-su được đưa lên trời và ngự bên hữu Thiên Chúa.` },

  // ── Glorious: pentecost (Acts 2) ──
  { slug: 'pentecost-hail-mary-1', ref: 'Acts 2:1', en: `And when the days of the Pentecost were accomplished, they were all together in one place,`, vi: `Khi đến ngày lễ Ngũ Tuần, mọi người đang tề tựu ở một nơi,` },
  { slug: 'pentecost-hail-mary-2', ref: 'Acts 2:2', en: `And suddenly there came a sound from heaven, as of a mighty wind coming, and it filled the whole house where they were sitting.`, vi: `bỗng từ trời phát ra một tiếng động, như tiếng gió mạnh ùa vào đầy cả căn nhà, nơi họ đang tụ họp.` },
  { slug: 'pentecost-hail-mary-3', ref: 'Acts 2:3', en: `And there appeared to them parted tongues as it were of fire, and it sat upon every one of them:`, vi: `Rồi họ thấy xuất hiện những hình lưỡi giống như lưỡi lửa tản ra đậu xuống từng người một.` },
  { slug: 'pentecost-hail-mary-4', ref: 'Acts 2:4', en: `And they were all filled with the Holy Ghost, and they began to speak with divers tongues, according as the Holy Ghost gave them to speak.`, vi: `Và ai nấy đều được tràn đầy ơn Thánh Thần, họ bắt đầu nói các thứ tiếng khác, tuỳ theo khả năng Thánh Thần ban cho.` },
  { slug: 'pentecost-hail-mary-5', ref: 'Acts 2:6', en: `And when this was noised abroad, the multitude came together, and were confounded in mind, because that every man heard them speak in his own tongue.`, vi: `Nghe tiếng ấy, có nhiều người kéo đến. Họ kinh ngạc vì ai nấy đều nghe các ông nói tiếng bản xứ của mình.` },
  { slug: 'pentecost-hail-mary-6', ref: 'Acts 2:14', en: `But Peter standing up with the eleven, lifted up his voice, and spoke to them: Ye men of Judea, and all you that dwell in Jerusalem, be this known to you, and with your ears receive my words.`, vi: `Bấy giờ, ông Phê-rô đứng chung với Nhóm Mười Một lớn tiếng nói với họ rằng: "Thưa anh em miền Giu-đê và tất cả những người đang cư ngụ tại Giê-ru-sa-lem, xin biết cho điều này, và lắng nghe những lời tôi nói đây."` },
  { slug: 'pentecost-hail-mary-7', ref: 'Acts 2:36', en: `Therefore let all the house of Israel know most certainly, that God hath made both Lord and Christ, this same Jesus, whom you have crucified.`, vi: `Vậy toàn thể nhà Ít-ra-en phải biết chắc điều này: Đức Giê-su mà anh em đã treo trên thập giá, Thiên Chúa đã đặt Người làm Đức Chúa và làm Đấng Ki-tô."` },
  { slug: 'pentecost-hail-mary-8', ref: 'Acts 2:38', en: `But Peter said to them: Do penance, and be baptized every one of you in the name of Jesus Christ, for the remission of your sins: and you shall receive the gift of the Holy Ghost.`, vi: `Ông Phê-rô đáp: "Anh em hãy sám hối, và mỗi người hãy chịu phép rửa nhân danh Đức Giê-su Ki-tô, để được ơn tha tội; và anh em sẽ nhận được ân huệ là Thánh Thần."` },
  { slug: 'pentecost-hail-mary-9', ref: 'Acts 2:41', en: `They therefore that received his word, were baptized; and there were added in that day about three thousand souls.`, vi: `Vậy những ai đã đón nhận lời ông, đều chịu phép rửa. Và hôm ấy đã có thêm khoảng ba ngàn người theo đạo.` },
  { slug: 'pentecost-hail-mary-10', ref: 'Acts 2:41', en: `They therefore that received his word, were baptized; and there were added in that day about three thousand souls.`, vi: `Vậy những ai đã đón nhận lời ông, đều chịu phép rửa. Và hôm ấy đã có thêm khoảng ba ngàn người theo đạo.` },

  // ── Glorious: assumption (Song 2,4; Ps 16,45; Jdt 13,15; Rom 6) ──
  { slug: 'assumption-hail-mary-1', ref: 'Song 2:10', en: `Behold my beloved speaketh to me: Arise, make haste, my love, my dove, my beautiful one, and come.`, vi: `Người yêu của tôi lên tiếng bảo: "Dậy đi em, bạn tình của anh, người đẹp của anh, hãy ra đây nào!"` },
  { slug: 'assumption-hail-mary-2', ref: 'Song 2:11', en: `For winter is now past, the rain is over and gone.`, vi: `Tiết đông giá lạnh đã qua, mùa mưa đã dứt, đã xa lắm rồi.` },
  { slug: 'assumption-hail-mary-3', ref: 'Ps 16:10', en: `Because thou wilt not leave my soul in hell; neither wilt thou suffer thy Holy One to see corruption.`, vi: `Vì Chúa chẳng đành bỏ mặc con trong cõi âm ty, không để kẻ hiếu trung này hư nát trong phần mộ.` },
  { slug: 'assumption-hail-mary-4', ref: 'Jdt 15:9', en: `Thou art the glory of Jerusalem, thou art the joy of Israel, thou art the honour of our people.`, vi: `Bà làm cho Giê-ru-sa-lem hãnh diện, cho Ít-ra-en vinh hiển, cho giống nòi chúng ta được vinh dự lớn lao.` },
  { slug: 'assumption-hail-mary-5', ref: 'Song 4:7', en: `Thou art all fair, O my love, and there is not a spot in thee.`, vi: `Bạn tình ơi, toàn thân nàng xinh đẹp, nơi nàng chẳng một chút vết nhơ.` },
  { slug: 'assumption-hail-mary-6', ref: 'Jdt 13:18', en: `Blessed art thou, O daughter, by the Lord the most high God, above all women upon the earth.`, vi: `Này trang nữ kiệt, bà được Thiên Chúa Tối Cao ban phúc hơn tất cả các phụ nữ trên cõi đất này.` },
  { slug: 'assumption-hail-mary-7', ref: 'Ps 45:14', en: `All the glory of the king's daughter is within in golden borders,`, vi: `Ðẹp lộng lẫy, này đây công chúa, mặc xiêm y dệt gấm thêu vàng,` },
  { slug: 'assumption-hail-mary-8', ref: 'Rev 12:1', en: `And a great sign appeared in heaven: A woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars:`, vi: `Rồi có điềm lớn xuất hiện trên trời: một người Phụ Nữ, mình khoác mặt trời, chân đạp mặt trăng, và đầu đội triều thiên mười hai ngôi sao.` },
  { slug: 'assumption-hail-mary-9', ref: 'Ps 45:13', en: `And the daughters of Tyre with gifts, yea, all the rich among the people, shall entreat thy countenance.`, vi: `Thiếu nữ thành Tia mang lễ tới, phú hào trong xứ đến cầu ân.` },
  { slug: 'assumption-hail-mary-10', ref: 'Rom 6:5', en: `For if we have been planted together in the likeness of his death, we shall be also in the likeness of his resurrection.`, vi: `Thật vậy, vì chúng ta đã nên một với Đức Ki-tô nhờ được chết như Người đã chết, thì chúng ta cũng sẽ nên một với Người, nhờ được sống lại như Người đã sống lại.` },

  // ── Glorious: coronation (Rev 12; Song 2,6; Sir 24; Prov 8) ──
  { slug: 'coronation-hail-mary-1', ref: 'Rev 12:1', en: `And a great sign appeared in heaven: A woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars:`, vi: `Rồi có điềm lớn xuất hiện trên trời: một người Phụ Nữ, mình khoác mặt trời, chân đạp mặt trăng, và đầu đội triều thiên mười hai ngôi sao.` },
  { slug: 'coronation-hail-mary-2', ref: 'Song 6:10', en: `Who is she that cometh forth as the morning rising, fair as the moon, bright as the sun, terrible as an army set in array?`, vi: `Kìa bà nào xuất hiện như rạng đông, diễm kiều như vầng nguyệt, lộng lẫy tựa thái dương, oai hùng như đạo binh chỉnh tề hàng ngũ?` },
  { slug: 'coronation-hail-mary-3', ref: 'Sir 24:7', en: `I dwelt in the highest places, and my throne is in a pillar of a cloud.`, vi: `Ta cắm lều trên nơi cao thẳm và đặt ngai Ta trên cột mây.` },
  { slug: 'coronation-hail-mary-4', ref: 'Song 2:1', en: `I am the flower of the field, and the lily of the valleys.`, vi: `Em là đoá thủy tiên của Sa-rôn đồng bằng, là bông huệ thắm hồng trong thung lũng.` },
  { slug: 'coronation-hail-mary-5', ref: 'Sir 24:24', en: `I am the mother of fair love, and of fear, and of knowledge, and of holy hope.`, vi: `Ta là mẹ sinh ra yêu mến tốt đẹp, sự kính sợ, sự hiểu biết, sự trông cậy lành thánh.` },
  { slug: 'coronation-hail-mary-6', ref: 'Sir 24:24', en: `I am the mother of fair love, and of fear, and of knowledge, and of holy hope.`, vi: `Ta là mẹ sinh ra yêu mến tốt đẹp, sự kính sợ, sự hiểu biết, sự trông cậy lành thánh.` },
  { slug: 'coronation-hail-mary-7', ref: 'Sir 24:24', en: `I am the mother of fair love, and of fear, and of knowledge, and of holy hope.`, vi: `Ta là mẹ sinh ra yêu mến tốt đẹp, sự kính sợ, sự hiểu biết, sự trông cậy lành thánh.` },
  { slug: 'coronation-hail-mary-8', ref: 'Prov 8:17', en: `I love them that love me: and they that in the morning early watch for me, shall find me.`, vi: `Kẻ yêu ta sẽ được ta yêu lại, người tìm ta ắt sẽ gặp ta.` },
  { slug: 'coronation-hail-mary-9', ref: 'Sir 24:21', en: `He that hearkeneth to me, shall not be confounded: and they that work by me, shall not sin.`, vi: `Ai nghe lời Ta sẽ không phải thẹn thùng, ai hoạt động trong Ta sẽ không hề phạm tội.` },
  { slug: 'coronation-hail-mary-10', ref: 'Prov 8:35', en: `He that shall find me, shall find life, and shall have salvation from the Lord.`, vi: `Vì gặp được ta là gặp sự sống, và hưởng ân lộc Ðức Chúa ban cho.` },
];
